    maj.textContent = "Mise \u00e0 jour : 13 novembre 2026, 22 h 49";
    maj.style.cssText = "margin-right:auto;font:13px/1.3 system-ui,sans-serif;color:#4E5C6D";
    barre.appendChild(maj);
